cat > checks/transfer.py <<'EOF'
import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer


class Rec:
    def __init__(self, fail=False):
        self.events, self.fail = [], fail

    def publish(self, e):
        if self.fail:
            raise RuntimeError("pub")
        self.events.append(e)


def setup():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return balance(c, "a"), balance(c, "b"), c.execute("SELECT count(*) FROM ledger").fetchone()[0]


c = setup(); p = Rec()
transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1) and len(p.events) == 1 and not c.in_transaction

for args in [("a", "a", 1), ("a", "x", 1), ("x", "b", 1), ("a", "b", 0), ("a", "b", -1),
             ("a", "b", True), ("a", "b", 1.0), ("a", "b", "1"), ("a", "b", 101)]:
    c = setup(); p = Rec()
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(args)
    assert state(c) == (100, 20, 0) and not p.events and not c.in_transaction, args

# publication failure keeps the committed transfer
c = setup()
try:
    transfer(c, Rec(fail=True), "a", "b", 5)
except RuntimeError:
    pass
else:
    raise AssertionError
assert state(c) == (95, 25, 1) and not c.in_transaction
c.rollback(); assert state(c) == (95, 25, 1)

# database failure at each statement rolls back and does not publish
for bad in ["UPDATE accounts SET balance=balance-", "UPDATE accounts SET balance=balance+", "INSERT INTO ledger"]:
    c = setup()
    c.set_trace_callback(None)
    c.execute("CREATE TRIGGER t BEFORE INSERT ON ledger BEGIN SELECT RAISE(ABORT,'x'); END") if bad.startswith("INSERT") else None
    c.commit()

    class Conn:
        def __init__(self, real): self.real = real
        def execute(self, sql, params=()):
            if sql.startswith(bad):
                raise sqlite3.OperationalError("boom")
            return self.real.execute(sql, params)
        def commit(self): return self.real.commit()
        def rollback(self): return self.real.rollback()
    p = Rec()
    try:
        transfer(Conn(c), p, "a", "b", 5)
    except sqlite3.Error:
        pass
    else:
        raise AssertionError(bad)
    assert state(c) == (100, 20, 0) and not p.events and not c.in_transaction, bad

# commit failure
c = setup()
class CommitFail:
    def __init__(self, real): self.real = real
    def execute(self, *a): return self.real.execute(*a)
    def commit(self): raise sqlite3.OperationalError("commit")
    def rollback(self): return self.real.rollback()
p = Rec()
try:
    transfer(CommitFail(c), p, "a", "b", 5)
except sqlite3.OperationalError:
    pass
assert state(c) == (100, 20, 0) and not p.events
print("ok")
